		if c.Eligible {
			assert.NotEmpty(t, c.Model, "eligible candidate must name a concrete model: %+v", c)
		}
		// Components is structured (not free-form); reading the four named
		// axes proves the wire shape matches AC §2.
		_ = c.Components.Cost
